// Sentry JavaScript SDK - Self-hosted version
// This is a minimal implementation for offline use
// For production, download the full SDK from https://github.com/getsentry/sentry-javascript

(function() {
  'use strict';
  
  window.Sentry = window.Sentry || {};
  
  function Sentry() {
    this.config = {};
    this.initialized = false;
    this.breadcrumbs = [];
  }
  
  Sentry.prototype.init = function(options) {
    this.config = options || {};
    this.initialized = true;
    console.log('Sentry initialized (offline mode)');
  };
  
  Sentry.prototype.addBreadcrumb = function(breadcrumb) {
    this.breadcrumbs.push({
      ...breadcrumb,
      timestamp: new Date().toISOString()
    });
    
    // Keep only last 50 breadcrumbs
    if (this.breadcrumbs.length > 50) {
      this.breadcrumbs = this.breadcrumbs.slice(-50);
    }
    
    console.log('Sentry breadcrumb:', breadcrumb);
  };
  
  Sentry.prototype.captureException = function(exception, context) {
    const error = {
      exception: exception,
      context: context || {},
      breadcrumbs: this.breadcrumbs,
      timestamp: new Date().toISOString()
    };
    
    console.error('Sentry error (offline):', error);
  };
  
  Sentry.prototype.captureMessage = function(message, level, context) {
    const event = {
      message: message,
      level: level || 'info',
      context: context || {},
      breadcrumbs: this.breadcrumbs,
      timestamp: new Date().toISOString()
    };
    
    console.log('Sentry message (offline):', event);
  };
  
  Sentry.prototype.setUser = function(user) {
    this.config.user = user;
    console.log('Sentry user set:', user);
  };
  
  Sentry.prototype.setTag = function(key, value) {
    this.config.tags = this.config.tags || {};
    this.config.tags[key] = value;
    console.log('Sentry tag set:', key, value);
  };
  
  Sentry.prototype.setContext = function(key, context) {
    this.config.contexts = this.config.contexts || {};
    this.config.contexts[key] = context;
    console.log('Sentry context set:', key, context);
  };
  
  // Initialize Sentry instance
  window.Sentry = new Sentry();
  
})();